    def gslcblas(self):
        return ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    @property
    def gsl(self):
        return ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def idamax(self, n, x, incx):
        libcblas = self.gslcblas
        libgsl = self.gsl

        # Load the required functions from the GSL library
        c_idamax = libgsl.c_fun("cblas_idamax", [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int], ctypes.c_int)

        # Compute the index of the maximum absolute value in the array
        result = c_idamax(n, x, incx)

        return result

    def get_result(self):
        n = self.n
        x = self.x
        incx = self.incx

        # Compute the index of the maximum absolute value in the array
        result = self.idamax(n, x, incx)

