def choose_random_elements(rng, dest, k, src, n, size):
    gsl = load_gsl()
    if not gsl:
        raise RuntimeError("GSL library not found")
    rng_ptr = ctypes.c_void_p(rng)
    dest_ptr = ctypes.cast(ctypes.pointer(dest), ctypes.POINTER(ctypes.c_void_p))
    src_ptr = ctypes.cast(ctypes.pointer(src), ctypes.POINTER(ctypes.c_void_p))
    gsl.gsl_ran_choose(rng_ptr, dest_ptr, k, src_ptr, n, size)
    return dest

