    gsl = load_gsl()
    if not gsl:
        raise RuntimeError("GSL library not found")
    rng = ctypes.c_void_p(gsl.gsl_rng_alloc(ctypes.c_int(0)))
    return rng

def free_rng(rng):
    gsl = load_gsl()
    if not gsl:
        raise RuntimeError("GSL library not found")
    gsl.gsl_rng_free(ctypes.c_void_p(rng))

