# Define the GSLBlock class
class GSLBlock:
    def __init__(self, n):
        self.n = n
        self.ptr = None

    def allocate(self):
        self.ptr = gsl_block_alloc(self.n)

    def callocate(self):
        self.ptr = gsl_block_calloc(self.n)

    def free(self):
        if self.ptr is not None:
            gsl_block_free(self.ptr)
            self.ptr = None

