        success = False

    if success:
        try:
            block.callocate()
        except Exception as e:
            print(f"Exception occurred while initializing memory: {e}")
            success = False

    if success:
        try:
            block.free()
        except Exception as e:
            print(f"Exception occurred while freeing memory: {e}")
